"""
GameDev Agent Task Queue API
Sends tasks to GameDev agent via HTTP gateway
"""

import requests
import json
import sys
import time
from datetime import datetime

GAMEDEV_GATEWAY = "http://localhost:8644"
TIMEOUT = 300  # 5 minutes

def send_task(task_description: str, context: dict = None) -> dict:
    """
    Send a task to GameDev agent via gateway API

    Args:
        task_description: The task prompt
        context: Optional context dict (files, constraints, etc.)

    Returns:
        dict with status, response, session_id
    """
    payload = {
        "message": task_description,
        "context": context or {},
        "timestamp": datetime.utcnow().isoformat()
    }

    try:
        # Try API endpoint (if API_SERVER platform is enabled)
        response = requests.post(
            f"{GAMEDEV_GATEWAY}/api/chat",
            json=payload,
            timeout=TIMEOUT
        )

        if response.status_code == 200:
            return {
                "status": "success",
                "response": response.json(),
                "session_id": response.json().get("session_id")
            }
        else:
            return {
                "status": "error",
                "error": f"HTTP {response.status_code}: {response.text}"
            }

    except requests.exceptions.ConnectionError:
        return {
            "status": "error",
            "error": "Cannot connect to GameDev gateway. Is it running?"
        }
    except requests.exceptions.Timeout:
        return {
            "status": "timeout",
            "error": f"Task exceeded {TIMEOUT}s timeout"
        }
    except Exception as e:
        return {
            "status": "error",
            "error": str(e)
        }


def check_status() -> dict:
    """Check if GameDev gateway is reachable"""
    try:
        response = requests.get(f"{GAMEDEV_GATEWAY}/health", timeout=5)
        return {
            "status": "online" if response.status_code == 200 else "error",
            "gateway": GAMEDEV_GATEWAY
        }
    except:
        return {
            "status": "offline",
            "gateway": GAMEDEV_GATEWAY
        }


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python gamedev_api.py <task_description>")
        print("       python gamedev_api.py --status")
        sys.exit(1)

    if sys.argv[1] == "--status":
        status = check_status()
        print(json.dumps(status, indent=2))
        sys.exit(0 if status["status"] == "online" else 1)

    task = " ".join(sys.argv[1:])
    print(f"[{datetime.utcnow().isoformat()}] Sending task to GameDev agent...")
    print(f"Task: {task}\n")

    result = send_task(task)
    print(json.dumps(result, indent=2))

    sys.exit(0 if result["status"] == "success" else 1)
"}

